    a.call("claim",o->o.writeByte(0));int balance=sa.profile.coins;a.call("returnroom",null);check(room.phase==2&&room.viewerPhase(sa)==0&&room.viewerPhase(sb)==2,"P1 waits in room while P2 still has unopened rewards");
